from pathlib import Path
import json
ROOT=Path('../ai-dial-chat').resolve();M=json.loads(Path('manifest.json').read_text());SNAP=M['snapshot']
def ref(file,symbol=None):
 lines=(ROOT/file).read_text().splitlines();start=1;end=len(lines)
 if symbol:
  hits=[i for i,l in enumerate(lines) if symbol in l]
  if hits:start=max(1,hits[0]-2);end=min(len(lines),hits[0]+65)
 return {'file':file,'start':start,'end':end,**({'symbol':symbol} if symbol else {})}
def C(*items):return [dict(title=x.split('|')[0],body=x.split('|')[1]) for x in items]
def deck(id,title,series):return {'id':id,'shortTitle':title,'series':series,'snapshot':SNAP,'slides':[]}
def add(d,title,layout='cards',files=None,notes='',**kw):
 sources=[ref(*f) if isinstance(f,tuple) else ref(f) for f in files or ['docs/architecture.md','package.json']]
 d['slides'].append(dict(id=d['id'].replace('/','-')+'-'+str(len(d['slides'])+1).zfill(2),title=title,layout=layout,sources=sources,notes=notes,**kw))
def save(d):
 e=next(x for x in M['decks'] if x['id']==d['id']);p=Path('content/decks')/(d['id'].replace('/','-')+'.json');d['output']=e['output'];p.write_text(json.dumps(d,indent=2)+'\n');e.update(content=str(p),slideCount=len(d['slides']),status='authored',purpose=d['slides'][0].get('subtitle',d['shortTitle']))

