add(B,'Keep controller and DTO changes synchronized','code',kicker='Source excerpt from ChatController · direct completion proxy.',code="@Controller({ path: 'chat', version: '1' })\nexport class ChatController {\n  @Post('completions')\n  sendCompletion(@Req() req: Request,\n                 @Body() dto: ChatCompletionDto) {\n    const { at } = req.user as SessionUser;\n    return this.chatService.sendCompletion(dto, at);\n  }\n}",files=['apps/chat-api/src/chat/chat.controller.ts','apps/chat-api/src/chat/dto/chat-completion.dto.ts'],notes='This is an abridged source excerpt, not a new runnable controller. Imports, constructor injection and Swagger decorators are omitted for readability; the original source contains them. This direct /chat/completions endpoint is distinct from the conversation persistence and streaming workflow. Full source excerpts are retained by path and range in the index.')
add(B,'Regenerate the browser contract after API changes','flow',nodes=C('Controller + DTO|Swagger annotations','OpenAPI export|openapi-spec','Client generation|openapi-sdk','Drift check|openapi:check'),takeaway='npm run openapi runs the complete regeneration workflow.',files=['package.json','tools/openapi/check-client.mjs','apps/chat-api/src/openapi/openapi.config.ts','libs/chat-api-client/src/index.ts'],notes='The generated client is checked in. Update server definitions rather than editing generated methods. The operationIdFactory uses handler names, so naming the handler changes the browser-facing method. Commands shown here were not run because they would modify the repository artifacts.')
add(B,'Configure the runtime deliberately','table',headers=['Configuration','Responsibility'],rows=[['DIAL_CORE_URL','Core transport endpoint'],['AUTH_* settings','Session keys and provider configuration'],['RESPONSES_API_ENABLED','Server-only upstream dispatch switch'],['MCP_APP_SANDBOX_URL','Separate-origin MCP proxy URL']],files=['apps/chat-api/README.md','apps/chat-api/src/config/environment.config.ts'],notes='The exact required fields and defaults are in the backend README and environment schema. Use obvious demo values when experimenting; do not embed real secrets in code examples. Invalid required configuration fails at boot. The runtime also supports feature, theme, cookie and telemetry settings.')
add(B,'Run and verify the backend','code',kicker='From the repository root with configured environment values.',code='npm run start:api\n\nnpm exec nx run @epam/chat-api:typecheck\nnpm exec nx run @epam/chat-api:test\nnpm run build:api\n\n# API documentation is configured in main.ts.\n# Use the deployment environment reference for auth.',files=['package.json','apps/chat-api/src/main.ts'],notes='Nx resolves @epam/chat-api as the project name. The serve target builds/runs the backend, while the separate start:api:dev script uses HMR tooling. These application commands are documented, not run during presentation generation. Backend integration tests use mocked external clients.')
add(B,'Existing tests exercise contracts and failures','table',headers=['Area','Source evidence'],rows=[['Conversation controller','SSE, attach, errors and persistence integration specs'],['Authentication','Session, CSRF and strategy specs'],['Domain transport','Chat controller and service specs'],['Sandbox/static assets','App-owned asset and policy behavior tests']],files=['apps/chat-api/src/conversations/tests/conversation.controller.integration.spec.ts','apps/chat-api/src/auth/session/tests/session.guard.spec.ts','apps/chat-api/src/chat/tests/chat.controller.integration.spec.ts'],notes='The inspected test files provide concrete behavior expectations. Test presence alone is not a passing suite result, and the presentation QA does not substitute for backend security testing. Run focused tests and repository verification for a code change.')
add(B,'Operational tradeoffs shape deployment',cards=C('Process-local state|Generation registries and caches are not durable cross-pod coordination.','External dependencies|Core and identity-provider availability affect user workflows.','Policy exceptions exist|Unversioned themes and documented transport gaps remain in the source.'),files=['apps/chat-api/src/conversations/conversation-generation.service.ts','apps/chat-api/src/app/cache.config.ts','apps/chat-api/src/themes/theme.controller.ts'],notes='Encrypted-cookie authentication enables stateless session decryption across correctly configured pods, but it does not make every runtime mechanism distributed. Distinguish session storage from in-memory active-generation coordination. Use deployment-specific operational checks before adopting a multi-instance topology.')
