S=deck('apps/chat-overlay-sandbox','Overlay sandbox','Sandbox walkthrough');sf=['apps/chat-overlay-sandbox/README.md','apps/chat-overlay-sandbox/src/main.tsx']
add(S,'Overlay sandbox','cover',subtitle='A real browser host for exercising the chat overlay protocol.',chips=['Integration cases','Port 4300','Running chat required'],caption='apps/chat-overlay-sandbox',files=sf,notes='This is a React/Vite demonstration application, not an isolated MCP resource renderer. It hosts existing overlay clients against a running chat instance.')
add(S,'Each case demonstrates a distinct contract','table',headers=['Case','Demonstration'],rows=[['DirectOverlayCase','Mount into a host-owned region'],['ManagerOverlayCase','Floating widget controls'],['ConversationListCase','List, create, select, rename and delete'],['Features / auth cases','Live options and provider login UI modes']],files=['apps/chat-overlay-sandbox/README.md'],notes='EnabledFeaturesCase and AuthUiModeCase complete the set. Cases are actual source modules under src/cases. They are useful for reproducing integration behavior before embedding the overlay into a separate product.')
add(S,'Trace the host-to-chat handshake','flow',nodes=C('Sandbox page|Choose an integration case','ChatOverlay|Create iframe','Embedded chat|Readiness exchange','Host controls|Send requests / read events'),takeaway='Host allowlisting and overlay mode are prerequisites.',files=['libs/chat-overlay/src/lib/ChatOverlay.ts','apps/chat-overlay-sandbox/src/cases/DirectOverlayCase/DirectOverlayCase.tsx'],notes='The host API waits for the full ready-to-interact handshake. A blank iframe caused by frame-ancestors policy is not a protocol timeout to fix in the controls. Check server allowlisting and runtime overlay mode first.')
add(S,'Reproduce the local scenario','code',kicker='Configure the backend, then run both the chat and this sandbox.',code='OVERLAY_ENABLED=true\nALLOWED_IFRAME_ORIGINS=http://localhost:4300\n\n# In the shell that starts the sandbox:\nVITE_CHAT_OVERLAY_HOST=http://localhost:4207 \\\n  npm exec nx serve chat-overlay-sandbox',files=['apps/chat-overlay-sandbox/README.md','apps/chat-overlay-sandbox/vite.config.mts'],notes='The first two lines are backend environment configuration, not values to set only on the sandbox process. The host override is passed to the Vite sandbox. Run chat at 4207 and its backend at 5000 first. No real user data is required to open the page, but an authenticated deployment may require login for chat actions.')
add(S,'A direct overlay is a small integration','code',kicker='Checked pattern from examples/chat-overlay.ts.',code="const overlay = new ChatOverlay('#demo-chat', {\n  domain: 'http://localhost:4207',\n  theme: 'dark',\n});\nawait overlay.ready();\nawait overlay.setInputContent('Explain the demo');\n// Later: overlay.destroy();",files=['apps/chat-overlay-sandbox/src/cases/DirectOverlayCase/DirectOverlayCase.tsx','libs/chat-overlay/src/lib/ChatOverlay.ts'],notes='The complete example receives domain as a parameter, subscribes to an event and returns cleanup. The container must exist in the page. Changing input is a protocol operation; it does not automatically send a model request.')
add(S,'Deployment shares the main chat image',cards=C('Published route|The backend can serve the sandbox at /overlay-sandbox/.','Enable it explicitly|OVERLAY_SANDBOX_ENABLED controls exposure of the route.','Separate HTML policy|The backend supplies the sandbox style nonce and response policy.'),files=['apps/chat-overlay-sandbox/README.md','Dockerfile','apps/chat-api/src/app/static-assets.ts'],notes='The root Dockerfile builds this app with the frontend and backend. The deployed sandbox embeds the current origin. This same-origin deployment is intentional for this demo host and must not be copied to the MCP sandbox architecture.')
add(S,'Verify cases through the current targets','code',kicker='Nx targets come from the resolved project graph.',code='npm exec nx test chat-overlay-sandbox\nnpm exec nx build chat-overlay-sandbox\nnpm exec nx run chat-overlay-sandbox:typecheck',files=['apps/chat-overlay-sandbox/README.md','apps/chat-overlay-sandbox/package.json'],notes='The source includes seven test files for sandbox behavior. These suites were inspected but not run for the presentation task. The live integration requires the external chat deployment and its server policy, beyond what a mocked test can establish.')
add(S,'Interpret integration failures at the right layer',cards=C('Blank frame|Check chat CSP frame-ancestors and allowed host origin.','No ready event|Inspect protocol readiness after the iframe loads.','Login cannot complete|Verify the exact provider and configured UI mode.'),files=['apps/chat-overlay-sandbox/README.md','libs/chat-overlay/src/lib/ChatOverlay.ts'],notes='Same-window identity-provider login in an iframe depends on the provider tenant and browser policy. The sandbox exposes those choices for investigation; it cannot make an incompatible provider embeddable. Use it as a reproducible integration host rather than a proof of production compatibility.')
save(S)

S=deck('apps/mcp-app-sandbox','MCP sandbox proxy','Sandbox walkthrough');mf=['apps/mcp-app-sandbox/README.md','apps/mcp-app-sandbox/src/main.ts']
add(S,'MCP sandbox proxy','cover',subtitle='A separate-origin HTML bridge for the MCP Apps double-iframe boundary.',chips=['NestJS proxy page','Port 3100','Allowlist required'],caption='apps/mcp-app-sandbox',files=mf,notes='This small application serves the sandbox-proxy document used by the MCP UI renderer. It must be deployed on an origin distinct from the chat host. It is an infrastructure component of the rendering boundary, not a catalog demo.')
add(S,'Why a separate application exists','flow',nodes=C('Chat host|Trusted app origin','Proxy frame|Distinct host or port','Inner tool frame|Untrusted UI document','Message bridge|Validated communication'),takeaway='Same-origin hosting would defeat the intended isolation boundary.',files=mf+['apps/mcp-app-sandbox/src/app/sandbox-page.ts'],notes='The README and implementation adapt the MCP reference double-iframe pattern. A sandbox attribute alone is not the reason for this separate app; the distinct origin keeps the proxy and tool document out of the host origin. The inner document and bridge have their own constraints.')
add(S,'Request validation precedes HTML delivery','flow',nodes=C('GET /|Origin or Referer','Allowlist check|Resolve host origin','Denied request|403 when invalid','Allowed response|HTML and scoped CSP'),takeaway='No allowlist means no successful page response.',files=['apps/mcp-app-sandbox/src/app/sandbox.controller.ts','apps/mcp-app-sandbox/src/app/sandbox.service.ts'],notes='SandboxService uses an Origin header when present, then falls back to the Referer origin. A missing or unapproved origin is rejected. SandboxController sends text/html, CSP, nosniff, cross-origin resource policy and no-store. A raw GET without the required embedding context should fail.')
add(S,'Configure two sides of the connection','code',kicker='The sandbox origin must differ from the chat origin.',code='# Start the sandbox:\nMCP_APP_SANDBOX_ALLOWED_HOST_ORIGINS=http://localhost:4207 \\\n  npm exec nx serve mcp-app-sandbox\n\n# Configure chat-api separately:\nMCP_APP_SANDBOX_URL=http://localhost:3100',files=['apps/mcp-app-sandbox/README.md','apps/mcp-app-sandbox/src/config/environment.config.ts'],notes='The frontend receives the sandbox URL through the backend client-configuration pipeline. PORT defaults to 3100. Production should use the actual distinct HTTPS origins and the intended host allowlist. No secret values are required in this example.')
add(S,'The page and policy are app-owned',cards=C('Controller|Validates the caller context and sets response headers.','Service|Combines allowed origin, HTML and CSP construction.','Page builder|Creates the bridge document used by the nested renderer.'),files=['apps/mcp-app-sandbox/src/app/sandbox.controller.ts','apps/mcp-app-sandbox/src/app/sandbox.service.ts','apps/mcp-app-sandbox/src/app/csp.ts','apps/mcp-app-sandbox/src/app/sandbox-page.ts'],notes='main.ts intentionally disables Helmet generic CSP and frame blocking so the route can deliver its custom embedding policy. CORS is explicitly disabled for cross-origin script fetching. This route is designed for iframe navigation with origin validation, not a general data API.')
add(S,'A rendered MCP view needs the whole chain','flow',nodes=C('Message evidence|Tool and resource match','Host adapter|Fetch resource / call tool','MCP renderer|Configured sandbox URL','Proxy page|Nested UI lifecycle'),takeaway='Use the mcp-apps and attachment-canvas decks for the frontend contracts.',files=['libs/mcp-apps/src/models/mcp-apps.ts','libs/attachment-canvas/src/components/McpAppCanvasRenderer/McpAppCanvasRenderer.tsx','apps/mcp-app-sandbox/src/app/sandbox-page.ts'],notes='The sandbox alone does not discover tools or authenticate tool calls. Those operations are supplied by the host adapter and backend. To reproduce a full interaction, use a configured MCP-capable deployment and a real ui:// resource; this bundle does not manufacture a product screenshot of that interaction.')
add(S,'Build and check what exists','code',kicker='The resolved project has build, serve, lint and typecheck; no test target.',code='npm exec nx build mcp-app-sandbox\nnpm exec nx run mcp-app-sandbox:typecheck\nnpm exec nx run mcp-app-sandbox:lint\n\ndocker build -f apps/mcp-app-sandbox/Dockerfile \\\n  -t mcp-app-sandbox .',files=['apps/mcp-app-sandbox/package.json','apps/mcp-app-sandbox/README.md','apps/mcp-app-sandbox/Dockerfile'],notes='No source test files or test target were discovered for this application. Do not invent a passing test result or recommend a nonexistent target. Build/typecheck/lint commands are available; real isolation behavior needs a browser integration exercise with distinct origins.')
add(S,'Limits to carry into operations',cards=C('Exact origin matters|A host allowlist must match the deployed scheme, hostname and port.','Not a content service|The app serves a proxy document, not Core storage or user files.','Validation gap|No dedicated source tests were discovered in this project.'),files=mf+['apps/mcp-app-sandbox/src/app/sandbox.service.ts'],notes='The small source footprint does not reduce the importance of this boundary. Deployment-origin and browser-policy checks remain necessary. The presentation report records that no full live MCP/Core integration was exercised during this output-only documentation task.')
save(S)
